func:
// Checked every hour. Runs only if the last successful update was 24 h or more ago.
// "last_successful_update" is set when a whole cycle has finished successfully
// (in "Compare flows" or "Check update").
// After a boot/restart it is empty: start counting from now, so the gateway doesn't run at boot.
const DAY = 24 * 60 * 60 * 1000;
let last = flow.get("last_successful_update");
if (!last) {
    last = Date.now();
    flow.set("last_successful_update", last);
}
if (Date.now() - last < DAY) {
    node.status({fill:"grey", shape:"ring", text:"Next run after " + new Date(last + DAY).toLocaleString()});
    return null;    // stop here
}
node.status({fill:"blue", shape:"dot", text:"Running " + new Date().toLocaleString()});
return msg;

// ---- ThingsBoard settings ----
msg.tb = {
    url: "https://tb-staging.edgecomenergy.net",
    assetName: "github token"     // looked up by name, so the asset can be recreated
};

// ThingsBoard login (tenant admin), shared by the "Fleet config" flow
const login = global.get("tb_login") || {};
if (!login.username || !login.password) {
    node.status({fill:"red", shape:"ring", text:"No ThingsBoard login"});
    node.error('No ThingsBoard login: is the "Fleet config" flow installed and deployed?');
    return null;
}

// ThingsBoard REST API login: POST /api/auth/login -> { token, refreshToken }
msg.method = "POST";
msg.url = msg.tb.url + "/api/auth/login";
msg.headers = { "Content-Type": "application/json" };
msg.payload = { username: login.username, password: login.password };
msg.requestTimeout = 30000;
node.status({fill:"blue", shape:"dot", text:"ThingsBoard login"});
return msg;

// Find the asset by name: GET /api/tenant/assets?assetName=<name>
if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"TB login failed (" + msg.statusCode + ")"});
    node.error("ThingsBoard login failed (HTTP " + msg.statusCode + "): " + String(msg.payload).slice(0, 300));
    return null;
}
try {
    msg.tb.token = JSON.parse(msg.payload).token;
} catch (e) {
    node.error("ThingsBoard login response is not JSON");
    return null;
}

msg.method = "GET";
msg.url = msg.tb.url + "/api/tenant/assets?assetName=" + encodeURIComponent(msg.tb.assetName);
msg.headers = { "X-Authorization": "Bearer " + msg.tb.token };
msg.requestTimeout = 30000;
delete msg.payload;
return msg;

// Read the asset's server attributes by its id
if (msg.statusCode === 404) {
    node.status({fill:"red", shape:"ring", text:"Asset not found"});
    node.error('ThingsBoard asset "' + msg.tb.assetName + '" not found');
    return null;
}
if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"Find asset failed (" + msg.statusCode + ")"});
    node.error("Finding the ThingsBoard asset failed (HTTP " + msg.statusCode + "): " + String(msg.payload).slice(0, 300));
    return null;
}
let assetId;
try {
    assetId = JSON.parse(msg.payload).id.id;
} catch (e) {
    node.error("ThingsBoard asset response is not what was expected");
    return null;
}

msg.method = "GET";
msg.url = msg.tb.url + "/api/plugins/telemetry/ASSET/" + assetId +
    "/values/attributes/SERVER_SCOPE?keys=github_repo,github_branch,github_token,nr_username,nr_password";
msg.headers = { "X-Authorization": "Bearer " + msg.tb.token };
msg.requestTimeout = 30000;
delete msg.tb.token;
delete msg.payload;
return msg;

// Asset attributes: [{ key, value, lastUpdateTs }, ...] -> { github_repo: ..., ... }
if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"Read asset failed (" + msg.statusCode + ")"});
    node.error("Reading the ThingsBoard asset failed (HTTP " + msg.statusCode + "): " + String(msg.payload).slice(0, 300));
    return null;
}
const cfg = {};
try {
    JSON.parse(msg.payload).forEach(a => { cfg[a.key] = a.value; });
} catch (e) {
    node.error("ThingsBoard asset response is not JSON");
    return null;
}

const required = ["github_repo", "github_branch", "github_token", "nr_username", "nr_password"];
const missing = required.filter(k => !cfg[k]);
if (missing.length) {
    node.status({fill:"red", shape:"ring", text:"Missing: " + missing.join(", ")});
    node.error("Asset is missing server attributes: " + missing.join(", "));
    return null;
}

// Kept in memory only - nothing is saved in the flow
flow.set("ci_config", cfg);
node.status({fill:"green", shape:"dot", text:"Config OK: " + cfg.github_repo + "@" + cfg.github_branch});
return { payload: Date.now() };    // new message without secrets starts the update

// Settings come from ThingsBoard (see "Store config")
const cfg = flow.get("ci_config");
msg.ci = {
    repo: cfg.github_repo,                    // e.g. "edgecom-ai/iot_flows"
    branch: cfg.github_branch,                // e.g. "main"
    nodeRed: "https://127.0.0.1/node-red",    // this gateway's Node-RED admin API
    selfFile: "ci-cd.json",                  // the updater itself, updated last
    selfTab: env.get("NR_FLOW_ID")            // id of this CI/CD tab (built-in)
};

// Node-RED login (Admin API: POST /auth/token)
msg.method = "POST";
msg.url = msg.ci.nodeRed + "/auth/token";
msg.headers = { "Content-Type": "application/x-www-form-urlencoded" };
msg.payload = "client_id=node-red-admin&grant_type=password&scope=*" +
    "&username=" + encodeURIComponent(cfg.nr_username) +
    "&password=" + encodeURIComponent(cfg.nr_password);
node.status({fill:"blue", shape:"dot", text:"Logging in"});
return msg;

// Output 1: GitHub "list files" request
// Output 2: revoke the previous run's token (keeps old sessions from piling up)
if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"Login failed (" + msg.statusCode + ")"});
    node.error("Node-RED login failed (HTTP " + msg.statusCode + "): " + msg.payload);
    return [null, null];
}
let token;
try {
    token = JSON.parse(msg.payload).access_token;
} catch (e) {
    node.error("Login response is not JSON: " + msg.payload);
    return [null, null];
}

const oldToken = flow.get("api_token");
flow.set("api_token", token);

let revoke = null;
if (oldToken && oldToken !== token) {
    revoke = {
        method: "POST",
        url: msg.ci.nodeRed + "/auth/revoke",
        headers: {
            "Authorization": "Bearer " + oldToken,
            "Content-Type": "application/x-www-form-urlencoded"
        },
        payload: "token=" + encodeURIComponent(oldToken)
    };
}

// GitHub: list files in the repo root
msg.method = "GET";
msg.url = "https://api.github.com/repos/" + msg.ci.repo + "/contents?ref=" + encodeURIComponent(msg.ci.branch);
msg.headers = {
    "Authorization": "Bearer " + flow.get("ci_config").github_token,
    "Accept": "application/vnd.github+json",
    "User-Agent": "edgecom-gateway-updater",
    "X-GitHub-Api-Version": "2022-11-28"
};
msg.requestTimeout = 30000;
delete msg.payload;
node.status({fill:"green", shape:"dot", text:"Token OK"});
return [msg, revoke];

// Keep only the .json files in the repo root
if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"GitHub list failed (" + msg.statusCode + ")"});
    node.error("GitHub file list failed (HTTP " + msg.statusCode + "): " + String(msg.payload).slice(0, 300));
    return null;
}
let list;
try {
    list = JSON.parse(msg.payload);
} catch (e) {
    node.error("GitHub file list is not JSON");
    return null;
}

const files = list
    .filter(f => f.type === "file" && /\.json$/i.test(f.name))
    .map(f => f.path);

if (files.length === 0) {
    node.status({fill:"yellow", shape:"ring", text:"No flow files in repo"});
    return null;
}
node.status({fill:"green", shape:"dot", text:files.length + " file(s)"});
msg.payload = files;    // e.g. ["edgecom.json", "customer-x.json"]
return msg;             // the Split node sends one message per file

// One message per file: download it from GitHub as raw JSON text
msg.file = msg.payload;
msg.method = "GET";
msg.url = "https://api.github.com/repos/" + msg.ci.repo + "/contents/" +
    encodeURI(msg.file) + "?ref=" + encodeURIComponent(msg.ci.branch);
msg.headers = {
    "Authorization": "Bearer " + flow.get("ci_config").github_token,
    "Accept": "application/vnd.github.raw+json",
    "User-Agent": "edgecom-gateway-updater",
    "X-GitHub-Api-Version": "2022-11-28"
};
msg.requestTimeout = 30000;
delete msg.payload;
return msg;

// Turn the downloaded file into { file, tab, nodes, configs } (or { file, error }).
// Always returns a message so the Join completes.
const result = { file: msg.file };
try {
    if (msg.statusCode !== 200) {
        result.retry = true;     // network/GitHub problem: try again next hour
        throw new Error("download failed (HTTP " + msg.statusCode + ")");
    }
    const nodes = JSON.parse(msg.payload);
    if (!Array.isArray(nodes)) {
        throw new Error("not a Node-RED flow export (expected a JSON array)");
    }
    const tabs = nodes.filter(n => n.type === "tab");
    if (tabs.length !== 1) {
        throw new Error("file must contain exactly one flow tab, found " + tabs.length);
    }
    const tab = tabs[0];
    result.tab = tab;
    result.nodes = nodes.filter(n => n.z === tab.id);

    // Global config nodes (MQTT broker, TLS...) are not deployed, so each
    // gateway keeps its own; they only have to exist on the gateway
    result.configs = nodes.filter(n => n.type !== "tab" && n.z !== tab.id)
        .map(n => ({ id: n.id, type: n.type }));
} catch (e) {
    result.error = e.message;
}
msg.payload = result;
return msg;

// msg.flows = [flow1, flow2, flow3...] from GitHub
msg.flows = msg.payload;
const ok = msg.flows.filter(f => !f.error).length;
node.status({fill:"blue", shape:"dot", text:ok + "/" + msg.flows.length + " flow file(s) OK"});

// Read the flows deployed on this gateway (Admin API: GET /flows)
msg.method = "GET";
msg.url = msg.ci.nodeRed + "/flows";
msg.headers = { "Authorization": "Bearer " + flow.get("api_token") };
delete msg.payload;
return msg;

// msg.flows   = flows from GitHub: [{ file, tab, nodes, configs }, ...]
// msg.payload = everything deployed on this gateway (GET /flows)
// Each GitHub flow is matched to the local flow (tab) with the same NAME:
//   no flow with that name -> install it    (POST /flow)
//   one flow, different    -> update it     (PUT /flow/<local id>)
//   one flow, same         -> skip
//   several with that name -> skip + error
// ci-cd.json always goes to this updater tab, and is updated last.
function markSuccess() {
    flow.set("last_successful_update", Date.now());    // the hourly check waits 24 h from here
}

if (msg.statusCode !== 200) {
    node.status({fill:"red", shape:"ring", text:"Read local flows failed (" + msg.statusCode + ")"});
    node.error("Could not read local flows (HTTP " + msg.statusCode + "): " + String(msg.payload).slice(0, 300));
    return null;
}
let local;
try {
    local = JSON.parse(msg.payload);
} catch (e) {
    node.error("Local flows response is not JSON");
    return null;
}

// Ignore what may legitimately differ between gateways
function clean(n) {
    const c = Object.assign({}, n);
    delete c.credentials;    // never returned by GET /flows
    delete c.z;              // the flow's id can differ from gateway to gateway
    return c;
}
function sortKeys(v) {
    if (Array.isArray(v)) return v.map(sortKeys);
    if (v && typeof v === "object") {
        const o = {};
        Object.keys(v).sort().forEach(k => { o[k] = sortKeys(v[k]); });
        return o;
    }
    return v;
}
function signature(tab, nodes) {
    return JSON.stringify(sortKeys({
        label: tab.label || "",
        disabled: !!tab.disabled,
        info: tab.info || "",
        env: tab.env || [],
        nodes: nodes.map(clean).sort((x, y) => (x.id < y.id ? -1 : 1))
    }));
}
// A new updater must at least compile before it replaces this one
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
function brokenFunctions(nodes) {
    return nodes.filter(n => n.type === "function").filter(n => {
        try { new AsyncFunction("msg", n.func); return false; } catch (e) { return true; }
    }).map(n => n.name || n.id);
}

const localIds = new Set(local.map(n => n.id));
const results = [], updates = [];
let selfUpdate = null, retry = false;

for (const f of msg.flows) {
    const say = text => results.push({ ci: msg.ci, changed: false, payload: f.file + ": " + text });
    if (f.error) {
        if (f.retry) retry = true;
        say("ERROR - " + f.error);
        continue;
    }
    const isSelf = f.file === msg.ci.selfFile;

    // Find the local flow
    let target;
    if (isSelf) {
        target = local.find(n => n.type === "tab" && n.id === msg.ci.selfTab);
        if (!target) { say("ERROR - updater tab not found on this gateway"); continue; }
    } else {
        const same = local.filter(n => n.type === "tab" && n.label === f.tab.label);
        if (same.length > 1) {
            say('ERROR - ' + same.length + ' flows named "' + f.tab.label + '" on this gateway, skipped');
            continue;
        }
        target = same[0];
        if (target && target.id === msg.ci.selfTab) {
            say('ERROR - "' + f.tab.label + '" is the name of the updater tab, skipped');
            continue;
        }
    }
    const targetId = target ? target.id : null;

    // Node ids must not already be used by another flow on this gateway
    const elsewhere = new Set(local.filter(n => n.id !== targetId && n.z !== targetId).map(n => n.id));
    const clash = f.nodes.filter(n => elsewhere.has(n.id)).map(n => n.id);
    if (clash.length) {
        say("ERROR - node ids already used by another flow: " + clash.slice(0, 5).join(", ") + ", skipped");
        continue;
    }
    // Config nodes the flow uses (MQTT broker, TLS...) must exist on this gateway
    const used = JSON.stringify(f.nodes);
    const missing = (f.configs || []).filter(c => !localIds.has(c.id) && used.includes('"' + c.id + '"'));
    if (missing.length) {
        say("ERROR - this gateway has no config node " + missing.map(c => c.type + " " + c.id).join(", ") + ", skipped");
        continue;
    }

    const want = { label: f.tab.label, disabled: !!f.tab.disabled, info: f.tab.info || "", env: f.tab.env || [] };
    if (target && signature(want, f.nodes) === signature(target, local.filter(n => n.z === targetId))) {
        say("up to date");
        continue;
    }
    if (isSelf) {
        const broken = brokenFunctions(f.nodes);
        if (broken.length || !f.nodes.some(n => n.type === "inject")) {
            say("ERROR - new updater looks broken (" + (broken.join(", ") || "no inject node") + "), not installed");
            continue;
        }
    }

    const m = {
        ci: msg.ci,
        file: f.file,
        changed: true,
        action: target ? "update" : "install",
        flowId: targetId,
        update: Object.assign({}, want, {
            nodes: f.nodes.map(n => { const c = Object.assign({}, n); delete c.credentials; return c; })
        }),
        payload: f.file + ": " + (target ? "different, updating flow " + targetId : "not on this gateway, installing")
    };
    if (isSelf) selfUpdate = m; else updates.push(m);
}

// "Check update" records the success when the last update has finished
// and then sends the updater's own update (so it always goes last)
if (updates.length) {
    flow.set("ci_pending", { left: updates.length, ok: !retry, self: selfUpdate });
} else {
    flow.set("ci_pending", null);
    if (!retry) markSuccess();
    if (selfUpdate) updates.push(selfUpdate);
}

const todo = updates.length;
node.status({fill: retry ? "red" : (todo ? "yellow" : "green"), shape:"dot",
    text: todo + " to install/update" + (retry ? ", download errors (retry in 1 h)" : "")});
return [results.concat(updates)];

// install: POST /flow           (new flow; Node-RED picks the flow id, node ids are kept)
// update:  PUT /flow/<local id>  (only this flow restarts)
const install = msg.action === "install";
msg.method = install ? "POST" : "PUT";
msg.url = msg.ci.nodeRed + (install ? "/flow" : "/flow/" + msg.flowId);
msg.headers = {
    "Authorization": "Bearer " + flow.get("api_token"),
    "Content-Type": "application/json"
};
msg.payload = Object.assign({}, msg.update);
if (!install) msg.payload.id = msg.flowId;
msg.requestTimeout = 60000;     // the gateway may take a while to restart the flow
return msg;

// Output 1: result for the debug panel
// Output 2: the updater's own update, sent after the last other update
function markSuccess() {
    flow.set("last_successful_update", Date.now());    // the hourly check waits 24 h from here
}

const ok = msg.statusCode === 200;
const what = msg.action === "install" ? "INSTALL" : "UPDATE";
if (ok) {
    msg.payload = msg.file + ": " + what + " OK";
    node.status({fill:"green", shape:"dot", text:what + " OK " + msg.file});
} else {
    msg.payload = msg.file + ": " + what + " FAILED (HTTP " + msg.statusCode + ") " + String(msg.payload).slice(0, 300);
    node.status({fill:"red", shape:"ring", text:what + " failed " + msg.file});
    node.error(msg.payload);
}

let next = null;
const p = flow.get("ci_pending");
if (msg.file !== msg.ci.selfFile && p) {
    p.left -= 1;
    if (!ok) p.ok = false;
    if (p.left <= 0) {
        flow.set("ci_pending", null);
        if (p.ok) markSuccess();     // otherwise the next hourly check tries again
        next = p.self;
    } else {
        flow.set("ci_pending", p);
    }
}
return [msg, next];
